const BYTES_PER_MB = 1024 * 1024;

/** Every archived issue of the org archived at or before `cutoff`. */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

/**
 * Permanently deletes archived issues with their label links, comments,
 * attachments and search documents, remembering each project's highest number.
 */
export async function purgeIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<PurgeResult> {
  const db = getDb();
  return db.transaction((tx) => {
    const rows = tx
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
        ),
      )
      .all();
    if (rows.length === 0) {
      return { issueIds: [], commentIds: [], storageMb: 0 };
    }

    const highest = new Map<string, number>();
    for (const row of rows) {
      highest.set(row.projectId, Math.max(highest.get(row.projectId) ?? 0, row.number));
    }
    for (const [projectId, maxNumber] of highest) {
      tx.insert(projectIssueCounters)
        .values({ projectId, orgId, maxNumber })
        .onConflictDoUpdate({
          target: projectIssueCounters.projectId,
          set: {
            maxNumber: sql`max(${projectIssueCounters.maxNumber}, ${maxNumber})`,
          },
        })
        .run();
    }

    const issueIds = rows.map((row) => row.id as IssueId);
    const commentIds: string[] = [];
    let storageMb = 0;

    for (let i = 0; i < issueIds.length; i += 200) {
      const chunk = issueIds.slice(i, i + 200);

      const commentRows = tx
        .select({ id: comments.id })
        .from(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)),
        )
        .all();
      const chunkCommentIds = commentRows.map((row) => row.id);
      commentIds.push(...chunkCommentIds);

      const files = tx
        .select({ sizeBytes: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .all();
      for (const file of files) {
        storageMb += Math.ceil(file.sizeBytes / BYTES_PER_MB);
      }

      for (let j = 0; j < chunkCommentIds.length; j += 200) {
        tx.delete(searchIndex)
          .where(
            and(
              orgPredicate(searchIndex.orgId, orgId),
              eq(searchIndex.subjectKind, "comment"),
              inArray(searchIndex.subjectId, chunkCommentIds.slice(j, j + 200)),
            ),
          )
          .run();
      }
      tx.delete(searchIndex)
        .where(
          and(
            orgPredicate(searchIndex.orgId, orgId),
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, chunk),
          ),
        )
        .run();
      tx.delete(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)),
        )
        .run();
      tx.delete(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .run();
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            inArray(issueLabels.issueId, chunk),
          ),
        )
        .run();
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, chunk)))
        .run();
    }

    return { issueIds, commentIds, storageMb };
  });
}

